gAJ(){return"\ub370\uc774\ud130\ub294 \ud734\ub300\ud3f0 \ubc16\uc73c\ub85c \ub098\uac00\uc9c0 \uc54a\uc544\uc694"},
gAI(){return"\ubaa8\ub4e0 \uacc4\uc0b0\uacfc \uc800\uc7a5\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \uc774\ub904\uc838\uc694. \uacc4\uc815\ub3c4 \ud074\ub77c\uc6b0\ub4dc\ub3c4 \uc5c6\uc5b4\uc694."},
