gpl(){return"\ud50c\ub79c \uc791\ub3d9 \ubc29\uc2dd"},
gpk(){return"\ub4a4\ub85c"},
gzB(){return"Road To\ub294 \uc7a5\uae30 \ud50c\ub79c\uacfc \ub9e4\uc77c\uc758 \uc870\uc815\uc744 \uacb0\ud569\ud574\uc694. \ud50c\ub79c\uc740 \ubaa9\ud45c\uae4c\uc9c0\uc758 \uae38\uc744 \uc815\ud558\uace0, \ub9e4\uc77c\uc758 \uc870\uc815\uc740 \uac01 \uc138\uc158\uc744 \uadf8\ub0a0 \uc0c1\ud0dc\uc5d0 \ub9de\ucdb0\uc694. \ubaa8\ub4e0 \uacc4\uc0b0\uc740 \ud734\ub300\ud3f0\uc5d0\uc11c \uc774\ub904\uc838\uc694."},
