gzs(){return"\uc870\uc815\uc740 \u221235%\uc5d0\uc11c +10% \ubc94\uc704\ub97c \ub118\uc9c0 \uc54a\uace0, \uac00\ubcbc\uc6b4 \uc8fc\uc5d0\ub294 \uc808\ub300 \uc62c\ub77c\uac00\uc9c0 \uc54a\uc73c\uba70, \uc2e0\ud638\uac00 \uc5c7\uac08\ub9ac\uba74 \ud68c\ubcf5\uc744 \uc6b0\uc120\ud574\uc694. \uc774\uc720\ub294 \ud56d\uc0c1 \ubcf4\uc5ec \ub4dc\ub9ac\uace0, \ud55c \ubc88 \ud0ed\uc73c\ub85c \uc6d0\ub798 \ud50c\ub79c\ub300\ub85c \ud560 \uc218 \uc788\uc5b4\uc694."},
gzE(){return"4. \ub098\uc5d0\uac8c\uc11c \ubc30\uc6b0\ub294 \ubc29\ubc95"},
gzC(){return"\ub2a5\ub825\uc740 \ud55c \uc591\ubfd0 \uc544\ub2c8\ub77c \uc5bc\ub9c8\ub098 \ud798\ub4e4\uc5c8\ub294\uc9c0\ub85c \uc815\ud574\uc838\uc694. '\ub9e4\uc6b0 \uc26c\uc6c0'\uc73c\ub85c \ud45c\uc2dc\ud55c 30\ud68c\ub294 \uc5ec\uc720\uac00 \uc788\uc5c8\ub2e4\ub294 \ub73b\uc774\uace0, '\ub9e4\uc6b0 \ud798\ub4e6'\uc778 30\ud68c\ub294 \ud55c\uacc4\uc600\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694. \ucd5c\uadfc \uc138\uc158\uc77c\uc218\ub85d \ub354 \uc911\uc694\ud558\uac8c \ubcf4\uace0, 5\uc77c \ub118\uac8c \uc26c\uba74 \ucd94\uc815\uce58\uac00 \uc870\uae08 \ub0b4\ub824\uac00\uc694."},
gzD(){return"\ud53c\ub85c\ub294 \ud798\ub4e4\ub2e4\uace0 \ud45c\uc2dc\ud55c \uc138\uc158, \uc77c\uc2dc\uc815\uc9c0\ud55c \uc2dc\uac04, \uadf8\ub9ac\uace0 \uc774\ubc88 \uc8fc\uc5d0 \uc6d4\ud3c9\uade0\ubcf4\ub2e4 \ud6e8\uc52c \ub9ce\uc774 \ud588\ub294\uc9c0(\uc798 \uc54c\ub824\uc9c4 \ubd80\uc0c1 \uc704\ud5d8 \uc2e0\ud638)\ub97c \ud568\uaed8 \ubd10\uc694. \uafb8\uc900\ud568, \ud398\uc774\uc2a4(\ub2ec\ub9ac\uae30), \uc2e4\uc81c \uc8fc\uac04 \ud5a5\uc0c1, \uccb4\uc911\ub3c4 \ucd94\uc801\ud574\uc694."},
gzp(){return"5. \ud50c\ub79c\uc774 \ubc14\ub00c\ub294 \ub54c"},
gzo(){return"\uc804\uccb4 \ud50c\ub79c\uc740 \ub3d9\uc758\ud560 \ub54c\ub9cc \ubc14\ub00c\uc5b4\uc694. \uc6b4\ub3d9\uc77c\uc744 \ube60\ub728\ub838\uc744 \ub54c, \ud55c \uc591\uc774 \uadf8\ub0a0 \uc694\uccad\ub7c9\uacfc 20% \ub118\uac8c \ucc28\uc774 \ub0a0 \ub54c, \ub610\ub294 \ucd5c\uadfc \uc138 \ubc88 \uc911 \ub450 \ubc88\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ud655\uc2e4\ud788 \uc27d\uac70\ub098 \ud798\ub4e4\uc5c8\uc744 \ub54c \uc81c\uc548\ud574\uc694. \ud558\ub8e8 \ucee8\ub514\uc158\uc774 \ub098\ube74\ub2e4\uace0 \ub0a0\uc9dc\uac00 \ubc14\ub00c\uc9c0\ub294 \uc54a\uc544\uc694. \uc9c0\uae08 \ud398\uc774\uc2a4\ub97c \uc720\uc9c0\ud558\uac70\ub098, \uc548\uc804\ud55c \ubc94\uc704\uc5d0\uc11c \uac00\uc7a5 \ube60\ub978 \ud398\uc774\uc2a4\ub97c \uace0\ub97c \uc218 \uc788\uc5b4\uc694."},
gzA(){return"6. \uc694\uc57d\uacfc \ucd94\ucc9c"},
gzz(){return"\uc138\uc158\uc774 \ub05d\ub0a0 \ub54c\ub9c8\ub2e4 \ubaa9\ud45c \ub300\ube44 \uacb0\uacfc, \uac1c\uc778 \ucd5c\uace0 \uae30\ub85d \uc5ec\ubd80, \ucd94\uc815 \ub2a5\ub825\uc758 \ubcc0\ud654, \ub2e4\uc74c \uc138\uc158\uc744 \ubcf4\uc5ec \ub4dc\ub824\uc694. '\uc9c4\ud589'\uc5d0\uc11c\ub294 \ud558\ub8e8 \ub354 \uc26c\uae30, \ubd80\ud558 \uad00\ub9ac, \ud50c\ub79c \ub0a0\uc9dc \ub300\ube44 \uc2e4\uc81c \ud398\uc774\uc2a4 \uac19\uc740 \ucd94\ucc9c\uc744 \ubcfc \uc218 \uc788\uc5b4\uc694."},
gzT(){return"7. \uc790\ub3d9 \uce21\uc815"},
gzS(){return"\uc6b4\ub3d9\uc774 \uc9c0\uc6d0\ud55c\ub2e4\uba74 \ud734\ub300\ud3f0\uc774 \ud69f\uc218\ub97c \uc138\uac70\ub098, \uc790\uc138 \uc720\uc9c0 \uc2dc\uac04\uc774\ub098 GPS \uac70\ub9ac\ub97c \uce21\uc815\ud574\uc694. \uc5b8\uc81c\ub4e0 \uace0\uce58\uac70\ub098 \uc9c1\uc811 \ub05d\ub0bc \uc218 \uc788\uc5b4\uc694."},
gzP(){return"8. \ub0b4 \ub370\uc774\ud130"},
gzO(){return"\ubaa8\ub4e0 \uacc4\uc0b0\uacfc \uc800\uc7a5\uc740 \ud734\ub300\ud3f0\uc5d0\uc11c \uc774\ub904\uc838\uc694. \uacc4\uc815, \ud074\ub77c\uc6b0\ub4dc, \uad11\uace0\uac00 \uc5c6\uc5b4\uc694. \uc571\uc744 \uc0ad\uc81c\ud558\uba74 \ub370\uc774\ud130\ub3c4 \uc0ad\uc81c\ub3fc\uc694."},
gzy(){return"\uc911\uc694"},
gzx(){return"\uc774 \uaddc\uce59\uc740 \uc6b4\ub3d9 \uac00\uc774\ub4dc\uc77c \ubfd0 \uc758\ud559\uc801 \uc870\uc5b8\uc774 \uc544\ub2c8\uc5d0\uc694. \ud1b5\uc99d, \uc5b4\uc9c0\ub7ec\uc6c0, \uc228\ucc38\uc774 \ub290\uaef4\uc9c0\uba74 \uba48\ucd94\uc138\uc694. \ubd80\uc0c1\uc774\ub098 \uac74\uac15 \ubb38\uc81c\uac00 \uc788\ub2e4\uba74 \uc804\ubb38\uac00\uc640 \uc0c1\ub2f4\ud558\uc138\uc694."},
