gvP(){return"\uacc4\ud68d\ubcf4\ub2e4 \ub4a4\ucc98\uc838 \uc788\uc5b4\uc694"},
vQ(a){return""+a+"\uc77c \ub3d9\uc548 \ud558\uc9c0 \uc54a\uc558\uc5b4\uc694"},
gvW(){return"\uc5d0\ub108\uc9c0\uac00 \uc801\uc740 \ub0a0\uc5d0 \ub354 \uc218\uc6d4\ud574\uc694"},
gvV(){return"\uc624\ub298 \uc5d0\ub108\uc9c0\ub77c\uba74 \uac00\uc7a5 \ub4a4\ucc98\uc9c4 \ubaa9\ud45c\ub97c \uc9c4\ud589\ud558\uae30 \uc88b\uc544\uc694"},
